package com.school; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import com.school.academic.CourseRepository; import com.school.academic.SubjectRepository; import com.school.academic.Subject; import com.school.academic.Course; import java.util.List; @SpringBootTest public class MongoTest2 { @Autowired private CourseRepository courseRepository; @Autowired private SubjectRepository subjectRepository; @Test public void test() { List<Course> courses = courseRepository.findByProgramType("DIP_CSE"); System.out.println("FOUND "+courses.size()+" DIP_CSE COURSES"); for(Course c : courses) { System.out.println("COURSE ID: " + c.getId() + " PROGRAM: " + c.getProgramType()); List<Subject> subs = subjectRepository.findByCourseAndLevelNoAndSemesterNo(c, 5, 2); System.out.println("SUBJECTS FOR THIS COURSE: " + subs.size()); } } }